<script setup>
import { ref } from 'vue'
import SectionTitle from '../components/SectionTitle.vue'
import TaskStatus from '../components/TaskStatus.vue'
import MotorcycleIcon from '../components/MotorcycleIcon.vue'
import { api } from '../services/api'
import { workspace as s, refreshMotos } from '../services/workspace'
import { decimal, formatKm } from '../services/format'
import { useTask } from '../composables/useTask'
const {busy,error,notice,run}=useTask(), form=ref(null), editId=ref(null)
function open(m=null){editId.value=m?.id||null;form.value=m?{...m}:{marca:'',modelo:'',ano:new Date().getFullYear(),placa:'',km_atual:0,capacidade_tanque:'',volume_reserva:''}}
async function save(){await run(async()=>{const body={...form.value,capacidade_tanque:form.value.capacidade_tanque?decimal(form.value.capacidade_tanque):null,volume_reserva:form.value.volume_reserva==null||form.value.volume_reserva===''?null:decimal(form.value.volume_reserva),placa:form.value.placa.toUpperCase().replace(/[-\s]/g,'')};if(editId.value)await api.put('/motocicletas/'+editId.value,body);else await api.post('/motocicletas',body);form.value=null;await refreshMotos()},'Moto salva.')}
async function remove(m){if(!window.confirm('Excluir '+m.modelo+' e todo o histórico de manutenções, despesas e alertas? Esta ação não pode ser desfeita.'))return;await run(async()=>{await api.delete('/motocicletas/'+m.id);await refreshMotos()},'Moto excluída.')}
</script>
<template><div class="page-stack"><SectionTitle>Minha Garagem</SectionTitle><TaskStatus :busy="busy" :error="error" :notice="notice"/><div class="garage-grid"><article v-for="m in s.motos" :key="m.id" class="motorcycle-card"><div class="motorcycle-art motorcycle-art-lime"><MotorcycleIcon/></div><div class="motorcycle-card-content"><h3>{{m.marca}} {{m.modelo}}</h3><p>{{m.placa}} · {{m.ano}}</p><p>{{formatKm(m.km_atual)}} km</p><div class="form-actions"><button class="button button-lime" :disabled="busy" @click="open(m)">Editar / KM</button><button class="button button-danger" :disabled="busy" @click="remove(m)">Excluir</button></div></div></article><button class="add-motorcycle" :disabled="busy" @click="open()"><span>+</span>Adicionar moto</button></div><form v-if="form" class="demo-form" @submit.prevent="save"><h3>{{editId?'Editar moto':'Nova moto'}}</h3><fieldset :disabled="busy"><div class="form-grid"><label class="field">Marca<input v-model="form.marca" required maxlength="255"/></label><label class="field">Modelo<input v-model="form.modelo" required maxlength="255"/></label><label class="field">Ano<input v-model="form.ano" type="number" min="1900" max="2100" required/></label><label class="field">Placa<input v-model="form.placa" required maxlength="8" placeholder="ABC1D23"/></label><label class="field">Quilometragem atual<input v-model="form.km_atual" type="number" min="0" max="4294967295" required/></label><label class="field">Capacidade total do tanque (L)<input v-model="form.capacidade_tanque" inputmode="decimal" pattern="[0-9]+([,.][0-9]{1,2})?" placeholder="Ex.: 12,00"/></label><label class="field">Volume da reserva (L)<input v-model="form.volume_reserva" inputmode="decimal" pattern="[0-9]+([,.][0-9]{1,2})?" placeholder="Ex.: 2,00"/></label></div><p class="field-hint">Tanque e reserva são opcionais; consulte o manual da moto. A reserva deve ser menor que a capacidade total. Atualize o odômetro para acompanhar seus alertas. A quilometragem não pode diminuir.</p><div class="form-actions"><button class="button button-black">Salvar</button><button class="button button-ghost" type="button" @click="form=null">Cancelar</button></div></fieldset></form></div></template>
